Input: {"question": "487th refers to which type of unit?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0326-ba046843c625:d00", "start": 0, "end": 159, "text": "487th Air Expeditionary Wing The 487th Air Expeditionary Wing is a provisional United States Air Force unit assigned to the United States Air Forces in Europe."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0326-ba046843c625:d00", "start": 160, "end": 230, "text": "As a provisional unit, it may be activated or inactivated at any time."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0326-ba046843c625:d00", "start": 231, "end": 338, "text": "The unit's last known assignment was in 2003 at Cairo West Air Base, Egypt, during Operation Iraqi Freedom."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0326-ba046843c625:d00", "start": 339, "end": 442, "text": "The first predecessor of the wing is the 487th Bombardment Group, a United States Army Air Forces unit."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0326-ba046843c625:d00", "start": 443, "end": 478, "text": "It was activated in September 1943."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0326-ba046843c625:d00", "start": 479, "end": 587, "text": "After training in the United States, it deployed to the European Theater of Operations , where it engaged in"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0326-ba046843c625:d01", "start": 0, "end": 102, "text": "487th Bombardment Squadron The 487th Bombardment Squadron is an inactive United States Air Force unit."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0326-ba046843c625:d01", "start": 103, "end": 203, "text": "Its last was assigned to the 340th Bombardment Wing, stationed at Whiteman Air Force Base, Missouri."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0326-ba046843c625:d01", "start": 204, "end": 243, "text": "It was inactivated on 1 September 1963."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0326-ba046843c625:d01", "start": 244, "end": 372, "text": "Established as a B-25 Mitchell medium bomber squadron in mid-1942, trained by Third Air Force in the southeastern United States."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0326-ba046843c625:d01", "start": 373, "end": 644, "text": "Deployed to IX Bomber Command in Egypt initially in March 1943 via Air Transport Command South Atlantic Route through Caribbean, Brazil, Liberia, Central Africa and Sudan, then reassigned to Mediterranean Theater of Operations (MTO), and to XII Bomber Command in Tunisia."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0326-ba046843c625:d01", "start": 645, "end": 654, "text": "Supported"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0326-ba046843c625:d02", "start": 0, "end": 94, "text": "487th Fighter Squadron The 487th Fighter Squadron is an inactive United States Air Force unit."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0326-ba046843c625:d02", "start": 95, "end": 180, "text": "Its last assignment was with 352d Fighter Group stationed at Camp Kilmer, New Jersey."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0326-ba046843c625:d02", "start": 181, "end": 209, "text": "Activated in September 1942."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0326-ba046843c625:d02", "start": 210, "end": 290, "text": "Trained with P-47 Thunderbolts under First Air Force in northeast United States."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0326-ba046843c625:d02", "start": 291, "end": 385, "text": "Deployed to European Theater of Operations, July 1943 as heavy bomber fighter escort squadron."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0326-ba046843c625:d02", "start": 386, "end": 562, "text": "Replaced Thunderbolts with long-range P-51D Mustangs, July 1944, P-47s reassigned to IX Fighter Command for tactical fighter-bomber missions supporting ground forces in France."}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0326-ba046843c625:d02", "start": 563, "end": 673, "text": "Deployed to Belgium in December 1944 to supplement IX Fighter Command tactical air forces during Battle of the"}}, "candidates": [{"candidate_id": "C0", "answer": "Air Expeditionary Wing", "card_ids": ["ramdocs-0326-ba046843c625:d00:c0"]}, {"candidate_id": "C1", "answer": "Bombardment Squadron", "card_ids": ["ramdocs-0326-ba046843c625:d01:c0"]}, {"candidate_id": "C2", "answer": "Fighter Squadron", "card_ids": ["ramdocs-0326-ba046843c625:d02:c0"]}], "original_cards": [{"doc_id": "ramdocs-0326-ba046843c625:d00", "card_id": "ramdocs-0326-ba046843c625:d00:c0", "entity": "487th", "scope": "unit type", "claim": "The 487th refers to an Air Expeditionary Wing.", "answer": "Air Expeditionary Wing", "quote": "487th Air Expeditionary Wing The 487th Air Expeditionary Wing is a provisional United States Air Force unit assigned to the United States Air Forces in Europe.", "original_document_number": 1}, {"doc_id": "ramdocs-0326-ba046843c625:d01", "card_id": "ramdocs-0326-ba046843c625:d01:c0", "entity": "487th", "scope": "United States Air Force", "claim": "The 487th refers to a Bombardment Squadron.", "answer": "Bombardment Squadron", "quote": "487th Bombardment Squadron The 487th Bombardment Squadron is an inactive United States Air Force unit.", "original_document_number": 2}, {"doc_id": "ramdocs-0326-ba046843c625:d02", "card_id": "ramdocs-0326-ba046843c625:d02:c0", "entity": "487th", "scope": "type of unit", "claim": "The 487th refers to a Fighter Squadron.", "answer": "Fighter Squadron", "quote": "487th Fighter Squadron The 487th Fighter Squadron is an inactive United States Air Force unit.", "original_document_number": 3}], "initial_answers": ["Air Expeditionary Wing", "Bombardment Squadron", "Fighter Squadron"]}
